        let mut owners = Vec::with_capacity(SLOTS + 1);
        let (_, metrics) = measure(|| {
            for _ in 0..=SLOTS {
                owners.push(Box::new(7u8));
            }
            std::hint::black_box(&owners);
        });
        assert!(metrics.invalid);
        assert!(metrics.live > 0);
        drop(owners);
    }
